import{_ as r,o as a,c as o,a2 as e}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"房间功能 · 新手教程","description":"","frontmatter":{},"headers":[],"relativePath":"features/rooms.md","filePath":"features/rooms.md","lastUpdated":1785772843000}'),n={name:"features/rooms.md"};function l(s,t,d,i,h,g){return a(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="房间功能-·-新手教程" tabindex="-1">房间功能 · 新手教程 <a class="header-anchor" href="#房间功能-·-新手教程" aria-label="Permalink to &quot;房间功能 · 新手教程&quot;">​</a></h1><blockquote><p>和好友一起看片、共享屏幕，从这一篇开始。</p></blockquote><hr><h2 id="_1-功能概述" tabindex="-1">1. 功能概述 <a class="header-anchor" href="#_1-功能概述" aria-label="Permalink to &quot;1. 功能概述&quot;">​</a></h2><p><strong>房间（Room）</strong> 是 ZViewer 多人互动的核心。你可以创建一个房间，邀请好友加入，一起同步观看视频、共享屏幕画面，或通过语音聊天实时交流。</p><p>核心能力：</p><ul><li><strong>同步观看</strong>：房主播放、暂停、跳转，所有人的画面保持一致。</li><li><strong>屏幕共享</strong>：分享端实时传输自己的屏幕或应用窗口。</li><li><strong>观众管理</strong>：房主可以踢人、禁言、审批加入、转交房主。</li><li><strong>弹幕与评论</strong>：边看边聊，支持 Bilibili 弹幕和画笔批注。</li><li><strong>断线保护</strong>：房主短暂断线，房间不会立即关闭，观众继续观看。</li></ul><hr><h2 id="_2-房间两种模式对比" tabindex="-1">2. 房间两种模式对比 <a class="header-anchor" href="#_2-房间两种模式对比" aria-label="Permalink to &quot;2. 房间两种模式对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比项</th><th>🎬 一起看（Watch Together）</th><th>🖥️ 屏幕共享（Screen Share）</th></tr></thead><tbody><tr><td><strong>做什么</strong></td><td>所有人同步观看同一个影片链接</td><td>分享端将自己的屏幕/窗口实时广播</td></tr><tr><td><strong>适合场景</strong></td><td>一起追剧、看电影</td><td>演示操作、远程协作、游戏直播</td></tr><tr><td><strong>播放控制</strong></td><td>房主全权控制，观众可申请控制</td><td>分享端控制自己的画面</td></tr><tr><td><strong>影片来源</strong></td><td>粘贴在线视频链接，或从房间列表添加</td><td>分享端本地屏幕/窗口捕获</td></tr><tr><td><strong>网络要求</strong></td><td>房主带宽 ≥ 影片码率即可</td><td>上传带宽 ≥ 分享分辨率码率</td></tr><tr><td><strong>延迟</strong></td><td>低（同步播放，无传输延迟）</td><td>中等（WebRTC 实时传输）</td></tr><tr><td><strong>观众数</strong></td><td>几乎无上限</td><td>受分享端上行带宽限制</td></tr></tbody></table><blockquote><p>还有 <strong>OBS 推流模式（<code>stream-push</code>）</strong>，适合专业直播场景，详见<a href="/features/screenshare">屏幕共享与推流</a>。</p></blockquote><hr><h2 id="_3-创建房间步骤" tabindex="-1">3. 创建房间步骤 <a class="header-anchor" href="#_3-创建房间步骤" aria-label="Permalink to &quot;3. 创建房间步骤&quot;">​</a></h2><p>创建一个房间只需三步：</p><ol><li><strong>打开首页</strong>，点击页面中央的 <strong>「开始共享」</strong> 按钮，或右上角的 <strong>「创建房间」</strong>。</li><li><strong>选择模式</strong>：在弹出的窗口中，选择 <strong>「一起看」</strong> 或 <strong>「屏幕共享」</strong>。</li><li><strong>自动进入房间</strong>：系统立即创建房间，你自动成为 <strong>房主（Host）</strong>，进入房间界面。</li></ol><blockquote><p>💡 <strong>提示</strong>：创建房间不需要注册账号。首次使用时，系统会提示你设置一个<strong>昵称</strong>，方便好友识别。</p></blockquote><hr><h2 id="_4-房间界面详解" tabindex="-1">4. 房间界面详解 <a class="header-anchor" href="#_4-房间界面详解" aria-label="Permalink to &quot;4. 房间界面详解&quot;">​</a></h2><p>进入房间后，你会看到四个主要区域：</p><h3 id="顶部栏" tabindex="-1">顶部栏 <a class="header-anchor" href="#顶部栏" aria-label="Permalink to &quot;顶部栏&quot;">​</a></h3><ul><li><strong>房间名称</strong>：显示当前房间的名称，点击可修改。</li><li><strong>房间号</strong>：一串数字 ID，发送给好友用于加入。</li><li><strong>在线人数</strong>：显示当前在线观众数。</li><li><strong>「邀请」按钮</strong>：点击弹出分享方式。</li><li><strong>「设置」按钮</strong>：齿轮图标，点击打开房间设置面板。</li><li><strong>「退出房间」按钮</strong>：退出并关闭房间（仅房主可关闭）。</li></ul><h3 id="播放器区域-一起看模式" tabindex="-1">播放器区域（一起看模式） <a class="header-anchor" href="#播放器区域-一起看模式" aria-label="Permalink to &quot;播放器区域（一起看模式）&quot;">​</a></h3><p>中央主区域是视频播放器，支持：</p><ul><li><strong>播放/暂停</strong>：点击画面或按空格键。</li><li><strong>进度条</strong>：拖拽跳转进度。</li><li><strong>音量控制</strong>：鼠标悬停调节。</li><li><strong>倍速播放</strong>：支持 0.5× ~ 2× 倍速。</li><li><strong>全屏</strong>：点击右下角全屏图标。</li></ul><blockquote><p>屏幕共享模式下，中央区域显示分享端的实时画面。</p></blockquote><h3 id="底部三列卡片" tabindex="-1">底部三列卡片 <a class="header-anchor" href="#底部三列卡片" aria-label="Permalink to &quot;底部三列卡片&quot;">​</a></h3><p>播放器下方有三列卡片，点按展开：</p><table tabindex="0"><thead><tr><th>卡片</th><th>内容</th></tr></thead><tbody><tr><td><strong>📋 影片列表</strong></td><td>当前房间已添加的所有影片，可切换、排序、新增</td></tr><tr><td><strong>💬 聊天</strong></td><td>实时评论——支持文字消息、弹幕模式和画笔批注</td></tr><tr><td><strong>👥 观众列表</strong></td><td>在线观众，显示昵称和角色（房主/观众）</td></tr></tbody></table><h3 id="右侧面板-房间信息" tabindex="-1">右侧面板（房间信息） <a class="header-anchor" href="#右侧面板-房间信息" aria-label="Permalink to &quot;右侧面板（房间信息）&quot;">​</a></h3><p>点击右侧边缘的 <strong>「▶」</strong> 箭头，展开房间信息面板，包含三个 Tab。</p><hr><h2 id="_5-房间信息面板-三个-tab" tabindex="-1">5. 房间信息面板（三个 Tab） <a class="header-anchor" href="#_5-房间信息面板-三个-tab" aria-label="Permalink to &quot;5. 房间信息面板（三个 Tab）&quot;">​</a></h2><h3 id="📄-信息-tab" tabindex="-1">📄 信息 Tab <a class="header-anchor" href="#📄-信息-tab" aria-label="Permalink to &quot;📄 信息 Tab&quot;">​</a></h3><ul><li><strong>房间号</strong>：复制发送给好友，对方在首页输入即可加入。</li><li><strong>分享链接</strong>：直接复制链接，发送给好友点击即可加入。</li><li><strong>房间名称</strong>：房主可修改房间的显示名称。</li><li><strong>当前模式</strong>：显示「一起看」或「屏幕共享」。</li></ul><h3 id="👥-观众-tab" tabindex="-1">👥 观众 Tab <a class="header-anchor" href="#👥-观众-tab" aria-label="Permalink to &quot;👥 观众 Tab&quot;">​</a></h3><p>房主可在此管理所有观众：</p><table tabindex="0"><thead><tr><th>操作</th><th>效果</th></tr></thead><tbody><tr><td><strong>「踢出」</strong></td><td>将该观众移出房间，无法自动重入</td></tr><tr><td><strong>「禁言」</strong></td><td>禁止该观众发送聊天消息（可再次点击「解禁」恢复）</td></tr><tr><td><strong>「转交房主」</strong></td><td>把房主身份交给该观众，原房主变为普通观众</td></tr></tbody></table><h3 id="🔒-权限-tab" tabindex="-1">🔒 权限 Tab <a class="header-anchor" href="#🔒-权限-tab" aria-label="Permalink to &quot;🔒 权限 Tab&quot;">​</a></h3><p>房主可以设置房间的访问控制：</p><table tabindex="0"><thead><tr><th>设置项</th><th>说明</th></tr></thead><tbody><tr><td><strong>房间密码</strong></td><td>开启后，加入者需输入密码才能进入</td></tr><tr><td><strong>最大人数</strong></td><td>限制房间最多容纳的观众数（含房主）</td></tr><tr><td><strong>加入审批</strong></td><td>开启后，新观众加入需房主在通知中点击「同意」或「拒绝」</td></tr><tr><td><strong>自动通过</strong></td><td>开启审批时，白名单或已关注用户自动通过，无需手动确认</td></tr></tbody></table><hr><h2 id="_6-邀请好友的三种方式" tabindex="-1">6. 邀请好友的三种方式 <a class="header-anchor" href="#_6-邀请好友的三种方式" aria-label="Permalink to &quot;6. 邀请好友的三种方式&quot;">​</a></h2><h3 id="方式一-房间号" tabindex="-1">方式一：房间号 <a class="header-anchor" href="#方式一-房间号" aria-label="Permalink to &quot;方式一：房间号&quot;">​</a></h3><p>在房间信息面板复制 <strong>房间号</strong>，发送给好友。好友在首页点击 <strong>「加入房间」</strong>，输入房间号即可进入。</p><h3 id="方式二-分享链接" tabindex="-1">方式二：分享链接 <a class="header-anchor" href="#方式二-分享链接" aria-label="Permalink to &quot;方式二：分享链接&quot;">​</a></h3><p>点击顶部栏的 <strong>「邀请」</strong> 按钮，选择 <strong>「复制链接」</strong>，将链接发送给好友。好友点击链接直接进入房间（如已设置密码，会提示输入）。</p><h3 id="方式三-房间列表" tabindex="-1">方式三：房间列表 <a class="header-anchor" href="#方式三-房间列表" aria-label="Permalink to &quot;方式三：房间列表&quot;">​</a></h3><p>好友在首页浏览 <strong>「公开房间」</strong> 列表，找到你的房间，点击 <strong>「加入」</strong> 按钮即可。房主可以在权限设置中将房间设为「公开」或「不公开」。</p><hr><h2 id="_7-加入房间的几种情况" tabindex="-1">7. 加入房间的几种情况 <a class="header-anchor" href="#_7-加入房间的几种情况" aria-label="Permalink to &quot;7. 加入房间的几种情况&quot;">​</a></h2><p>根据房主的设置，加入房间有不同的体验：</p><h3 id="✅-无密码-无需审批" tabindex="-1">✅ 无密码 + 无需审批 <a class="header-anchor" href="#✅-无密码-无需审批" aria-label="Permalink to &quot;✅ 无密码 + 无需审批&quot;">​</a></h3><p>点击链接或输入房间号后，<strong>直接进入房间</strong>，开始同步观看。</p><h3 id="🔑-有密码" tabindex="-1">🔑 有密码 <a class="header-anchor" href="#🔑-有密码" aria-label="Permalink to &quot;🔑 有密码&quot;">​</a></h3><p>进入房间前弹出 <strong>密码输入框</strong>，输入正确密码后进入。密码由房主在权限 Tab 中设置。</p><h3 id="⏳-需审批" tabindex="-1">⏳ 需审批 <a class="header-anchor" href="#⏳-需审批" aria-label="Permalink to &quot;⏳ 需审批&quot;">​</a></h3><p>房主开启了「加入审批」。你点击加入后，页面会显示 <strong>「等待房主同意」</strong>。房主会收到通知，点击「同意」后你才进入房间。</p><h3 id="🚫-房间已满" tabindex="-1">🚫 房间已满 <a class="header-anchor" href="#🚫-房间已满" aria-label="Permalink to &quot;🚫 房间已满&quot;">​</a></h3><p>如果房间人数达到「最大人数」上限，你会看到提示 <strong>「房间已满」</strong>，无法加入。</p><hr><h2 id="_8-观众管理操作" tabindex="-1">8. 观众管理操作 <a class="header-anchor" href="#_8-观众管理操作" aria-label="Permalink to &quot;8. 观众管理操作&quot;">​</a></h2><p>房主在右侧面板 <strong>「观众 Tab」</strong> 中，可以对每一位观众执行以下操作：</p><h3 id="踢出观众" tabindex="-1">踢出观众 <a class="header-anchor" href="#踢出观众" aria-label="Permalink to &quot;踢出观众&quot;">​</a></h3><ol><li>在观众列表中找到目标观众。</li><li>点击右侧的 <strong>「···」</strong> 更多菜单。</li><li>选择 <strong>「踢出」</strong>。</li><li>该观众被移出房间，并收到提示。</li></ol><blockquote><p>被踢出的观众不会自动重新加入，需要房主重新邀请。</p></blockquote><h3 id="禁言-解禁观众" tabindex="-1">禁言/解禁观众 <a class="header-anchor" href="#禁言-解禁观众" aria-label="Permalink to &quot;禁言/解禁观众&quot;">​</a></h3><ol><li>在观众列表中找到目标观众。</li><li>点击 <strong>「···」</strong> → <strong>「禁言」</strong>。</li><li>该观众将无法发送聊天消息，观众列表中显示 <strong>🔇</strong> 图标。</li><li>如需恢复，再次点击 <strong>「解禁」</strong>。</li></ol><h3 id="转交房主" tabindex="-1">转交房主 <a class="header-anchor" href="#转交房主" aria-label="Permalink to &quot;转交房主&quot;">​</a></h3><ol><li>点击目标观众旁的 <strong>「···」</strong> → <strong>「转交房主」</strong>。</li><li>确认后，该观众成为新房主，你变为普通观众。</li><li>新房主获得播放控制权、观众管理权和房间设置权。</li></ol><hr><h2 id="_9-房主断线保护机制" tabindex="-1">9. 房主断线保护机制 <a class="header-anchor" href="#_9-房主断线保护机制" aria-label="Permalink to &quot;9. 房主断线保护机制&quot;">​</a></h2><p>ZViewer 有完善的断线保护，避免房主短暂掉线导致房间崩溃：</p><table tabindex="0"><thead><tr><th>阶段</th><th>行为</th></tr></thead><tbody><tr><td><strong>断线瞬间（0~10 秒）</strong></td><td>服务器接管播放状态，继续向观众广播当前进度，观众观看<strong>无感知</strong></td></tr><tr><td><strong>断线中（10 秒~10 分钟）</strong></td><td>观众可自由控制播放（暂停/跳转），房间正常运行</td></tr><tr><td><strong>超时关闭（10 分钟后）</strong></td><td>房主仍未重连，房间自动关闭，所有观众被移出</td></tr><tr><td><strong>房主重连</strong></td><td>若在 10 分钟内重新连接，房主自动恢复控制权，播放状态同步回最新位置</td></tr></tbody></table><blockquote><p>💡 <strong>建议</strong>：如果只是网络波动，无需担心——房间会等你回来。</p></blockquote><hr><h2 id="_10-常见问题" tabindex="-1">10. 常见问题 <a class="header-anchor" href="#_10-常见问题" aria-label="Permalink to &quot;10. 常见问题&quot;">​</a></h2><h3 id="q-最多可以有多少人一起看" tabindex="-1">Q：最多可以有多少人一起看？ <a class="header-anchor" href="#q-最多可以有多少人一起看" aria-label="Permalink to &quot;Q：最多可以有多少人一起看？&quot;">​</a></h3><p>A：没有硬性上限，但建议根据房主网络带宽和服务器负载控制在 50 人以内以获得最佳体验。</p><h3 id="q-加入房间需要注册账号吗" tabindex="-1">Q：加入房间需要注册账号吗？ <a class="header-anchor" href="#q-加入房间需要注册账号吗" aria-label="Permalink to &quot;Q：加入房间需要注册账号吗？&quot;">​</a></h3><p>A：不需要。首次加入时输入一个<strong>昵称</strong>即可，无需注册。但注册后可以保留头像和昵称设置。</p><h3 id="q-为什么我看不到影片画面" tabindex="-1">Q：为什么我看不到影片画面？ <a class="header-anchor" href="#q-为什么我看不到影片画面" aria-label="Permalink to &quot;Q：为什么我看不到影片画面？&quot;">​</a></h3><p>A：检查以下几点：</p><ul><li>影片链接是否有效（是否可公开访问）。</li><li>是否被浏览器广告拦截插件拦截（尝试关闭插件或使用隐身模式）。</li><li>是否处于审批等待状态，尚未被房主同意加入。</li></ul><h3 id="q-屏幕共享模式下-对方能看到我的整个屏幕吗" tabindex="-1">Q：屏幕共享模式下，对方能看到我的整个屏幕吗？ <a class="header-anchor" href="#q-屏幕共享模式下-对方能看到我的整个屏幕吗" aria-label="Permalink to &quot;Q：屏幕共享模式下，对方能看到我的整个屏幕吗？&quot;">​</a></h3><p>A：你可以选择共享<strong>整个屏幕</strong>、<strong>某个应用窗口</strong>或<strong>浏览器标签页</strong>。建议只共享需要的窗口，保护隐私。</p><h3 id="q-房主退出后房间会怎样" tabindex="-1">Q：房主退出后房间会怎样？ <a class="header-anchor" href="#q-房主退出后房间会怎样" aria-label="Permalink to &quot;Q：房主退出后房间会怎样？&quot;">​</a></h3><p>A：房主退出时会自动关闭房间，所有观众被移出。如果只是断线，有 10 分钟保护期（见第 9 节）。</p><h3 id="q-如何修改房间密码" tabindex="-1">Q：如何修改房间密码？ <a class="header-anchor" href="#q-如何修改房间密码" aria-label="Permalink to &quot;Q：如何修改房间密码？&quot;">​</a></h3><p>A：房主在右侧面板的 <strong>「权限 Tab」</strong> 中，找到「房间密码」项，点击 <strong>「修改」</strong> 输入新密码即可。</p><h3 id="q-手机端可以加入房间吗" tabindex="-1">Q：手机端可以加入房间吗？ <a class="header-anchor" href="#q-手机端可以加入房间吗" aria-label="Permalink to &quot;Q：手机端可以加入房间吗？&quot;">​</a></h3><p>A：可以。ZViewer 是 Web 应用，手机浏览器打开链接即可加入，支持基本的播放同步和聊天功能。</p><hr><blockquote><p>更多问题？查看<a href="/guide/faq">常见问题 FAQ</a> 或联系管理员。</p></blockquote>',93)])])}const c=r(n,[["render",l]]);export{u as __pageData,c as default};
